            completeFunc: ffi_tinkle_ffi_rust_future_complete_u64,
            freeFunc: ffi_tinkle_ffi_rust_future_free_u64,
            liftFunc: FfiConverterUInt64.lift,
            errorHandler: FfiConverterTypeFfiError_lift
        )
}
